import type {
  QuizData,
  QuizLevelThreshold,
  QuizResponses,
  QuizResult,
} from './types';

export function getOptionScore(
  quiz: QuizData,
  questionId: string,
  optionIndex: number
): number {
  const question = quiz.questions.find((q) => q.id === questionId);
  if (!question) return 0;
  const option = question.options[optionIndex];
  if (!option) return 0;
  return option.score;
}

export function getMaxQuestionScore(
  quiz: QuizData,
  questionId: string
): number {
  const question = quiz.questions.find((q) => q.id === questionId);
  if (!question) return 0;
  return Math.max(...question.options.map((o) => o.score));
}

export function findLevel(
  score: number,
  thresholds: QuizLevelThreshold[]
): QuizLevelThreshold | null {
  for (const t of thresholds) {
    if (score >= t.minScore && score <= t.maxScore) return t;
  }
  return null;
}

