24	   * URL is built locally and the user lands on the results page regardless of
25	   * Cakemail's response.
26	   *
27	   * Optional: provide EITHER `cakemailFormUrl` (built-in best-effort POST) OR
28	   * `onSubmit` (host owns delivery). If both are given, `onSubmit` wins.
29	   */
30	  cakemailFormUrl?: string;
31	  /**
32	   * Override for how the captured contact is delivered. Receives the multipart
33	   * form-data the engine assembled (email, firstname, tags). Use it to route the
34	   * submission through your own endpoint (e.g. a CAPTCHA-gated proxy) instead of
35	   * POSTing straight to Cakemail. Unlike the built-in POST, this hook is
36	   * authoritative: if it throws, the engine shows the thrown message and keeps
37	   * the user on the capture step (no redirect) so they can retry. Resolve to
38	   * proceed.
39	   */
40	  onSubmit?: (formData: FormData) => Promise<void>;
41	  /**
42	   * Extra content rendered inside the capture form, just above the submit button.
43	   * Use it to mount a pre-submit widget the host needs at submit time (e.g. a
44	   * CAPTCHA whose token your `onSubmit` reads). The engine treats it as opaque.
45	   */
46	  captureExtras?: React.ReactNode;
47	  /**
48	   * Required. Used to build the results redirect path (`/quiz/{slug}/results/?...`).
49	   */
50	  quizSlug: string;
51	  introTitle?: string;
52	  introBody?: string;
53	  /** Icon in the intro card's chip. Defaults to the privacy icon. */
54	  introIcon?: string;
55	  startButtonLabel?: string;
56	  /**
57	   * Label on the button that finishes the quiz and goes to the results page.
58	   * With `capturePosition: 'end'` that is the capture form's submit button; with
59	   * `'start'` it is the last question's "next" button.
60	   */
61	  submitButtonLabel?: string;
62	  showCorrectness?: boolean;
63	  /** Heading above the capture form. Defaults to wording that suits the position. */
64	  captureHeading?: string;
65	  /**
66	   * Body copy under the capture heading. Shown only by the end-of-quiz capture
67	   * card; the start gate is a compact panel with no room for a paragraph.
68	   */
69	  captureBody?: string;
70	  /**
71	   * Label on the capture form's own button. Defaults to `submitButtonLabel` at
72	   * the end of a quiz and to `startButtonLabel` on a start gate, since that
73	   * button leads to question 1 rather than to the result.
74	   */
75	  captureButtonLabel?: string;
76	  /**
77	   * Small print shown under the submit button on the capture step. Use it to
78	   * tell the user what they're opting into (e.g. "You'll also receive ...").
79	   */
80	  captureFootnote?: string;
81	  /**
82	   * Tags applied to the contact on submission, sent as Cakemail's
83	   * `tags[<name>]=true` form fields. Use for audience segmentation that the
84	   * email platform's automations can trigger on (e.g. ['aiquiz']).
85	   */
86	  submissionTags?: string[];
87	  /**
88	   * When set, the contact is also tagged with `${levelTagPrefix}${overallLevel}`
89	   * (e.g. prefix 'aiquiz-' + level 'high-risk' => tag 'aiquiz-high-risk'), so a
90	   * nurture sequence can branch on the quiz result tier. Ignored on a start
91	   * gate, where nothing has been answered yet.
92	   */
93	  levelTagPrefix?: string;
94	}
