96	type StepKind = 'intro' | 'question' | 'capture';
97	
98	interface Step {
99	  kind: StepKind;
100	  index: number;
101	}
102	
103	export default function QuizStepper({
104	  quiz,
105	  cakemailFormUrl,
106	  onSubmit,
107	  captureExtras,
108	  quizSlug,
109	  introTitle,
110	  introBody,
111	  introIcon = 'privacy',
112	  startButtonLabel = 'Start the quiz',
113	  submitButtonLabel = 'See my results',
114	  showCorrectness = false,
115	  captureHeading,
116	  captureBody,
117	  captureButtonLabel,
118	  captureFootnote = "You'll also be subscribed to our list. You can unsubscribe at any time.",
119	  submissionTags,
120	  levelTagPrefix,
121	}: QuizStepperProps) {
122	  const capturePosition = quiz.capturePosition ?? 'end';
123	  // Order questions once on mount. Shuffling lives inside a `useState`
124	  // initializer so each user gets a stable order across re-renders and
125	  // back-button navigation. Section order is always preserved.
126	  const [orderedQuestions] = useState<QuizQuestion[]>(() =>
127	    orderQuestions(quiz)
128	  );
129	  // Per-question option display order (arrays of original option indices).
130	  // Computed once on mount so a shuffled order stays stable across re-renders
131	  // and back-navigation. Scoring stores the original index, not the display
132	  // position, so shuffling never affects results.
133	  const [optionOrder] = useState<Record<string, number[]>>(() =>
134	    buildOptionOrder(quiz)
135	  );
136	  const steps = buildSteps(orderedQuestions, capturePosition);
137	  const [stepIndex, setStepIndex] = useState(0);
138	  const [responses, setResponses] = useState<QuizResponses>({});
139	  const [revealed, setRevealed] = useState<Record<string, boolean>>({});
140	  const [firstName, setFirstName] = useState('');
141	  const [email, setEmail] = useState('');
142	  const [submitting, setSubmitting] = useState(false);
143	  const [submitError, setSubmitError] = useState<string | null>(null);
144	  // True once the contact has been delivered. Only meaningful for a start gate,
145	  // where the back button can bring the taker back to an already-submitted
146	  // capture form; without this the second click would POST the same contact again.
147	  const [captured, setCaptured] = useState(false);
148	  const initialised = useRef(false);
149	  const startedRef = useRef(false);
150	
151	  useEffect(() => {
152	    if (initialised.current) return;
153	    initialised.current = true;
154	    window.history.replaceState({ quizStep: 0 }, '');
155	
156	    const onPop = (event: PopStateEvent) => {
157	      const next = event.state?.quizStep;
158	      if (typeof next === 'number' && next >= 0 && next < steps.length) {
159	        setStepIndex(next);
160	      }
161	    };
162	    window.addEventListener('popstate', onPop);
163	    return () => window.removeEventListener('popstate', onPop);
164	  }, [steps.length]);
165	
166	  // Fire a generic event whenever the step changes so the host page can react
167	  // (e.g. hide marketing chrome once the quiz is underway). The engine has no
168	  // opinion about what consumers do with this. `quiz:started` is a one-shot
169	  // event the first time a question appears, intended for analytics.
170	  useEffect(() => {
171	    const step = steps[stepIndex];
172	    window.dispatchEvent(
173	      new CustomEvent('quiz:step-changed', {
174	        detail: { kind: step.kind, index: stepIndex },
175	      })
176	    );
177	    if (!startedRef.current && step.kind === 'question') {
178	      startedRef.current = true;
179	      window.dispatchEvent(new CustomEvent('quiz:started'));
180	    }
181	  }, [stepIndex, steps]);
182	
183	  const goToStep = (next: number) => {
184	    if (next < 0 || next >= steps.length) return;
185	    window.history.pushState({ quizStep: next }, '');
186	    setStepIndex(next);
187	    if (typeof window !== 'undefined') {
188	      window.scrollTo({ top: 0, behavior: 'smooth' });
189	    }
190	  };
191	
192	  // Listen for a `quiz:start-requested` event so a host page can trigger the
193	  // quiz from its own chrome (e.g. a marketing hero "Start the Quiz" button).
194	  // No-op unless currently on the first step, so duplicate dispatches are safe.
195	  useEffect(() => {
196	    const onStartRequested = () => {
197	      if (stepIndex === 0) goToStep(1);
198	    };
199	    window.addEventListener('quiz:start-requested', onStartRequested);
200	    return () =>
201	      window.removeEventListener('quiz:start-requested', onStartRequested);
202	  }, [stepIndex, steps]);
203	
204	  const step = steps[stepIndex];
205	  const progress = computeProgress(step, steps, capturePosition);
206	
207	  // Score the quiz in the browser so the results URL is ready without a round
208	  // trip. Doing it client-side also means the taker lands on the results page
209	  // even if the ESP rejects the submission — they finished the quiz, they get
210	  // the result. The query shape depends on the result style: band carries
211	  // scores/levels; map-move carries the raw answers so the (stateless) results
212	  // page can rebuild the map.
213	  const scoreQuiz = (): { query: URLSearchParams; level: string } => {
214	    if (quiz.resultStyle === 'map-move') {
215	      return {
216	        query: buildMapMoveQuery(quiz, responses),
217	        level: computeMapMove(quiz, responses).framing ?? '',
218	      };
219	    }
220	    const result = computeQuizResult(quiz, responses);
221	    return { query: buildResultQuery(result), level: result.overallLevel };
222	  };
223	
224	  const goToResults = () => {
225	    const { query } = scoreQuiz();
226	    window.location.href = `/quiz/${quizSlug}/results/?${query.toString()}`;
227	  };
228	
229	  if (step.kind === 'intro') {
230	    return (
231	      <Shell progress={progress} showProgress={false}>
232	        <QuizIntroCard
233	          title={introTitle ?? quiz.title}
234	          body={introBody ?? quiz.intro}
235	          icon={introIcon}
236	          buttonLabel={startButtonLabel}
237	          onStart={() => goToStep(stepIndex + 1)}
238	        />
239	      </Shell>
240	    );
241	  }
242	
243	  if (step.kind === 'question') {
244	    const question = orderedQuestions[step.index];
245	    const chosenIndex = responses[question.id];
246	    const isRevealed = !!revealed[question.id];
247	
248	    const onPick = (optionIndex: number) => {
249	      setResponses((prev) => ({ ...prev, [question.id]: optionIndex }));
250	      setRevealed((prev) => ({ ...prev, [question.id]: true }));
251	    };
252	
253	    // On a start gate the capture step is already behind the taker, so the last
254	    // question is the end of the quiz: its "next" button goes to the results.
255	    const finishesQuiz = stepIndex === steps.length - 1;
256	
257	    return (
258	      <Shell progress={progress} showProgress>
259	        <QuestionScreen
260	          quiz={quiz}
261	          question={question}
262	          optionOrder={optionOrder[question.id]}
263	          chosenIndex={chosenIndex}
264	          revealed={isRevealed}
265	          showCorrectness={showCorrectness}
266	          onPick={onPick}
267	          nextLabel={finishesQuiz ? submitButtonLabel : 'Next'}
268	          onNext={finishesQuiz ? goToResults : () => goToStep(stepIndex + 1)}
269	        />
270	      </Shell>
271	    );
272	  }
273	
274	  // capture step
275	  // A start gate runs before question 1, so there is nothing to have answered.
276	  const allAnswered =
277	    capturePosition === 'start' ||
278	    quiz.questions.every((q) => q.id in responses);
279	
280	  const handleSubmit = async (e: React.SyntheticEvent) => {
281	    e.preventDefault();
282	    if (submitting) return;
283	
284	    // Back-navigated onto an already-submitted start gate: just move on rather
285	    // than delivering the same contact a second time.
286	    if (captured) {
287	      goToStep(stepIndex + 1);
288	      return;
289	    }
290	
291	    setSubmitError(null);
292	    setSubmitting(true);
293	
294	    // Only an end capture has answers to score and a result tier to tag with.
295	    const scored = capturePosition === 'end' ? scoreQuiz() : null;
296	
297	    const formData = new FormData();
298	    formData.append('email', email.trim());
299	    if (firstName.trim()) {
300	      formData.append('custom_attributes[firstname]', firstName.trim());
301	    }
302	    // Cakemail tags use a dict shape: `tags[<name>]=true`. Static tags from the
303	    // host plus an optional result-tier tag drive the nurture sequence.
304	    for (const tag of submissionTags ?? []) {
305	      formData.append(`tags[${tag}]`, 'true');
306	    }
307	    if (levelTagPrefix && scored?.level) {
308	      formData.append(`tags[${levelTagPrefix}${scored.level}]`, 'true');
309	    }
310	
311	    // Host-provided delivery wins and is authoritative: if it throws (e.g. a
312	    // CAPTCHA gate rejects the submission), surface the message and keep the user
313	    // on the capture step so they can retry — don't move on.
314	    if (onSubmit) {
315	      try {
316	        await onSubmit(formData);
317	      } catch (err) {
318	        setSubmitError(
319	          err instanceof Error
320	            ? err.message
321	            : 'Something went wrong. Please try again.'
322	        );
323	        setSubmitting(false);
324	        return;
325	      }
326	    } else if (cakemailFormUrl) {
327	      try {
328	        // `no-cors` fires the POST without requiring Cakemail to send back
329	        // CORS headers. We can't read the response, but for a marketing-form
330	        // submission we don't need to — Cakemail's double opt-in email is the
331	        // user's source of truth, not our success/error state.
332	        await fetch(cakemailFormUrl, {
333	          method: 'POST',
334	          mode: 'no-cors',
335	          body: formData,
336	        });
337	      } catch (err) {
338	        // Network failure only. Log so a real outage shows up in PostHog/console,
339	        // but still send the user on — they earned their result.
340	        console.error('quiz signup POST failed', err);
341	      }
342	    }
343	
344	    setCaptured(true);
345	
346	    // An end capture is the last step, so send the taker to their results. A
347	    // start gate hands off to the intro instead.
348	    if (scored) {
349	      window.location.href = `/quiz/${quizSlug}/results/?${scored.query.toString()}`;
350	      return;
351	    }
352	    setSubmitting(false);
353	    goToStep(stepIndex + 1);
354	  };
355	
356	  const captureProps = {
357	    email,
358	    onEmailChange: setEmail,
359	    onSubmit: handleSubmit,
360	    submitting,
361	    canSubmit: allAnswered && email.includes('@'),
362	    // A start gate's button begins the questions, so it falls back to the
363	    // "start" label, not the "finish" one: promising the result on a button
364	    // that leads to question 1 is a lie the taker notices immediately.
365	    submitButtonLabel:
366	      captureButtonLabel ??
367	      (capturePosition === 'start' ? startButtonLabel : submitButtonLabel),
368	    footnote: captureFootnote,
369	    error: submitError,
370	    extras: captureExtras,
371	  };
372	
373	  // The start gate is a compact panel that sits inside the cover's own layout;
374	  // the end capture is a standalone card at the finish of the quiz.
375	  if (capturePosition === 'start') {
376	    return (
377	      <CapturePanel
378	        {...captureProps}
379	        heading={captureHeading ?? 'Where should I send your result?'}
380	      />
381	    );
382	  }
383	
384	  return (
385	    <Shell progress={progress} showProgress>
386	      <CaptureCard
387	        {...captureProps}
388	        heading={captureHeading ?? 'Where should we send your results?'}
389	        body={
390	          captureBody ??
391	          "Enter your email and we'll show you your results and what they mean."
392	        }
393	        firstName={firstName}
394	        onFirstNameChange={setFirstName}
395	      />
396	    </Shell>
397	  );
398	}
399	
400	function Shell({
401	  progress,
402	  showProgress,
403	  children,
404	}: {
405	  progress: { current: number; total: number };
406	  showProgress: boolean;
407	  children: React.ReactNode;
408	}) {
409	  const pct = Math.round((progress.current / progress.total) * 100);
410	  return (
411	    <div className="quiz-stepper mx-auto w-full max-w-170">
412	      {showProgress ? (
413	        <div className="mb-6">
414	          <div className="text-quiz-ink-muted mb-1.5 flex items-center justify-between text-sm">
415	            <span>
416	              Step {progress.current} of {progress.total}
417	            </span>
418	            <span>{pct}%</span>
419	          </div>
420	          <div className="bg-quiz-hairline h-1.5 w-full overflow-hidden rounded-full">
421	            <div
422	              className="bg-quiz-accent-strong h-full transition-all duration-300"
423	              style={{ width: `${pct}%` }}
424	              role="progressbar"
425	              aria-valuenow={pct}
426	              aria-valuemin={0}
427	              aria-valuemax={100}
428	            />
429	          </div>
430	        </div>
431	      ) : null}
432	      {children}
433	    </div>
434	  );
435	}
