437	function QuestionScreen({
438	  quiz,
439	  question,
440	  optionOrder,
441	  chosenIndex,
442	  revealed,
443	  showCorrectness,
444	  onPick,
445	  nextLabel,
446	  onNext,
447	}: {
448	  quiz: QuizData;
449	  question: QuizQuestion;
450	  /** Original option indices in display order; defaults to declared order. */
451	  optionOrder?: number[];
452	  chosenIndex: number | undefined;
453	  revealed: boolean;
454	  showCorrectness: boolean;
455	  onPick: (optionIndex: number) => void;
456	  /** "Next" for every question but the last one of a start-gated quiz. */
457	  nextLabel: string;
458	  onNext: () => void;
459	}) {
460	  const section = quiz.sections.find((s) => s.id === question.section);
461	  const maxOptionScore = Math.max(...question.options.map((o) => o.score));
462	  const userGotItRight =
463	    revealed &&
464	    chosenIndex !== undefined &&
465	    question.options[chosenIndex]?.score === maxOptionScore;
466	  const order = optionOrder ?? question.options.map((_, i) => i);
467	  // An answer locks only when picking it disclosed something the taker could
468	  // now act on: a quiz that marks answers right or wrong, or a question with
469	  // reveal copy. A reflective question discloses nothing, so let them change
470	  // their mind, which is the point of asking someone to think back over a
471	  // couple of sprints. They can also come back and change it with the back
472	  // button, since responses are keyed by question id.
473	  const answerLocked = revealed && (showCorrectness || !!question.reveal);
474	
475	  return (
476	    <div className="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-6 md:p-8">
477	      {section ? (
478	        <p className="text-quiz-accent-strong mb-2 text-sm">{section.label}</p>
479	      ) : null}
480	      <h2 className="text-quiz-ink mb-6 text-2xl font-bold md:text-3xl">
481	        {question.text}
482	      </h2>
483	      <ul className="space-y-2.5">
484	        {order.map((originalIndex, displayIndex) => {
485	          const option = question.options[originalIndex];
486	          if (!option) return null;
487	          const isChosen = chosenIndex === originalIndex;
488	          // The chip letter follows the *display* position, never the authored
489	          // one. With `randomizeOptions: 'shuffle'` the authored letter would
490	          // both come out jumbled (b, d, a, c) and leak the authoring pattern,
491	          // e.g. that "d" is always the context answer. It is a visual anchor
492	          // for the eye, carrying no meaning of its own.
493	          const letter = String.fromCharCode(97 + displayIndex);
494	          const isCorrect = showCorrectness && option.score === maxOptionScore;
495	          const showAsCorrectPick = revealed && isCorrect && userGotItRight;
496	          const showAsCorrectAnswer = revealed && isCorrect && !userGotItRight;
497	          // Only mark a pick "wrong" when the quiz scores answers. Reflective
498	          // quizzes (showCorrectness=false) have no wrong answer, so a chosen
499	          // option just reads as selected.
500	          const showAsWrong =
501	            showCorrectness && revealed && isChosen && !isCorrect;
502	          // Every option carries a 2px border and only the colour changes with
503	          // state. Selection needs the heavier weight to read, and swapping the
504	          // width instead would jog each tile by 3px as it is picked.
505	          let optionClasses =
506	            'w-full rounded-lg border-2 px-4 py-3 text-left text-base leading-snug transition focus:outline-none focus:ring-2 focus:ring-quiz-accent-strong focus:ring-offset-2';
507	          let chipClasses = 'bg-quiz-context-panel text-quiz-ink-muted';
508	          if (showAsCorrectPick) {
509	            optionClasses +=
510	              ' border-quiz-valuable-edge bg-quiz-valuable-tint text-quiz-ink';
511	            chipClasses = 'bg-quiz-valuable-strong text-white';
512	          } else if (showAsCorrectAnswer) {
513	            // Outline only, so it reads as a reference rather than a celebration.
514	            optionClasses +=
515	              ' border-quiz-valuable-edge bg-quiz-card text-quiz-ink';
516	            chipClasses = 'bg-quiz-valuable-tint text-quiz-valuable-strong';
517	          } else if (showAsWrong) {
518	            optionClasses +=
519	              ' border-quiz-slipping-edge bg-quiz-slipping-tint text-quiz-ink';
520	            chipClasses = 'bg-quiz-slipping-strong text-white';
521	          } else if (isChosen) {
522	            optionClasses +=
523	              ' border-quiz-accent-edge bg-quiz-accent-tint text-quiz-ink';
524	            chipClasses = 'bg-quiz-accent-strong text-white';
525	          } else if (answerLocked) {
526	            // The answer is settled, so mute what wasn't picked.
527	            optionClasses +=
528	              ' border-quiz-hairline bg-quiz-card text-quiz-ink-muted';
529	          } else {
530	            // Still changeable: keep the hover so it stays obviously pickable.
531	            optionClasses +=
532	              ' border-quiz-hairline bg-quiz-card text-quiz-ink hover:border-quiz-accent-edge hover:bg-quiz-accent-tint';
533	          }
534	          return (
535	            <li key={originalIndex}>
536	              <button
537	                type="button"
538	                onClick={() => !answerLocked && onPick(originalIndex)}
539	                disabled={answerLocked}
540	                className={`${optionClasses} flex items-start gap-3`}
541	                aria-pressed={isChosen}
542	              >
543	                <span
544	                  className={`flex size-6 shrink-0 items-center justify-center rounded-md text-sm font-medium transition ${chipClasses}`}
545	                  aria-hidden="true"
546	                >
547	                  {letter}
548	                </span>
549	                <span className="flex-1">{option.text}</span>
550	                {showAsCorrectPick ? (
551	                  <CorrectIcon />
552	                ) : showAsWrong ? (
553	                  <WrongIcon />
554	                ) : null}
555	              </button>
556	            </li>
557	          );
558	        })}
559	      </ul>
560	
561	      {revealed && question.reveal ? (
562	        <div
563	          className="bg-quiz-context-panel text-quiz-ink-secondary mt-6 rounded-xl p-4 text-base/relaxed"
564	          role="status"
565	          aria-live="polite"
566	        >
567	          <p className="whitespace-pre-line">
568	            {renderInlineMarkdown(question.reveal)}
569	          </p>
570	        </div>
571	      ) : null}
572	
573	      {revealed ? (
574	        <div className="mt-6 flex justify-end">
575	          <button type="button" onClick={onNext} className={PRIMARY_BUTTON}>
576	            {nextLabel}
577	          </button>
578	        </div>
579	      ) : null}
580	    </div>
581	  );
582	}
