584	interface CaptureFieldProps {
585	  email: string;
586	  onEmailChange: (v: string) => void;
587	  onSubmit: (e: React.SyntheticEvent) => void;
588	  submitting: boolean;
589	  canSubmit: boolean;
590	  submitButtonLabel: string;
591	  footnote: string;
592	  error: string | null;
593	  extras?: React.ReactNode;
594	}
595	
596	/**
597	 * The start gate: a tinted panel that sits at the bottom of the cover, so the
598	 * ask is visible next to what the taker is being offered. Email only, because
599	 * every extra field on a gate costs completions.
600	 */
601	function CapturePanel({
602	  heading,
603	  email,
604	  onEmailChange,
605	  onSubmit,
606	  submitting,
607	  canSubmit,
608	  submitButtonLabel,
609	  footnote,
610	  error,
611	  extras,
612	}: CaptureFieldProps & { heading: string }) {
613	  return (
614	    <form
615	      onSubmit={onSubmit}
616	      className="bg-quiz-context-panel rounded-xl p-4 md:p-5"
617	      noValidate
618	    >
619	      <label
620	        htmlFor="quiz-email"
621	        className="text-quiz-ink-secondary mb-2 block text-base"
622	      >
623	        {heading}
624	      </label>
625	      <div className="flex flex-col gap-2.5 sm:flex-row">
626	        <input
627	          id="quiz-email"
628	          type="email"
629	          autoComplete="email"
630	          required
631	          placeholder="name@work.com"
632	          value={email}
633	          onChange={(e) => onEmailChange(e.target.value)}
634	          className="border-quiz-hairline bg-quiz-card text-quiz-ink placeholder:text-quiz-ink-muted focus:border-quiz-accent-edge focus:ring-quiz-accent-edge min-w-0 flex-1 rounded-lg border-[0.5px] px-3.5 py-2.5 text-base focus:ring-1 focus:outline-none"
635	        />
636	        <button
637	          type="submit"
638	          disabled={!canSubmit || submitting}
639	          className={`shrink-0 ${PRIMARY_BUTTON}`}
640	          data-ph-capture-attribute-quiz-submit="true"
641	        >
642	          {submitting ? 'Submitting…' : submitButtonLabel}
643	        </button>
644	      </div>
645	
646	      {extras ? <div className="mt-3">{extras}</div> : null}
647	
648	      {error ? (
649	        <p className="text-quiz-slipping-strong mt-3 text-sm" role="alert">
650	          {error}
651	        </p>
652	      ) : null}
653	
