659	/** The end-of-quiz capture: a standalone card once the questions are done. */
660	function CaptureCard({
661	  heading,
662	  body,
663	  firstName,
664	  onFirstNameChange,
665	  email,
666	  onEmailChange,
667	  onSubmit,
668	  submitting,
669	  canSubmit,
