749	
750	// Minimal inline markdown: only `[label](url)` links. Kept inline so the
751	// engine has no markdown dependency when extracted.
752	function renderInlineMarkdown(text: string): React.ReactNode[] {
753	  const nodes: React.ReactNode[] = [];
754	  const linkRegex = /\[([^\]]+)\]\(([^)\s]+)\)/g;
755	  let lastIndex = 0;
756	  let match: RegExpExecArray | null;
757	  let key = 0;
758	  while ((match = linkRegex.exec(text)) !== null) {
759	    if (match.index > lastIndex) {
760	      nodes.push(text.slice(lastIndex, match.index));
761	    }
762	    const [, label, url] = match;
763	    const isExternal = /^https?:\/\//i.test(url);
764	    nodes.push(
765	      <a
766	        key={key++}
767	        href={url}
768	        {...(isExternal
769	          ? { target: '_blank', rel: 'noopener noreferrer' }
770	          : {})}
771	        className="text-quiz-accent-strong underline"
772	      >
773	        {label}
774	      </a>
775	    );
776	    lastIndex = linkRegex.lastIndex;
777	  }
778	  if (lastIndex < text.length) {
779	    nodes.push(text.slice(lastIndex));
780	  }
781	  return nodes.length > 0 ? nodes : [text];
782	}
783	
784	/**
785	 * The step order. The first step is the one the host page's marketing chrome
786	 * sits alongside.
787	 *
788	 * A start gate has no intro *step*: the cover is already the place to reassure
789	 * someone, and it has to happen before they hand over an email, not after. The
790	 * host page renders `QuizIntroCard` under the opt-in instead, so the gate's
791	 * button is the cover's only action and submitting it goes straight to
792	 * question 1.
793	 */
794	function buildSteps(
795	  questions: QuizQuestion[],
796	  capturePosition: CapturePosition
797	): Step[] {
798	  const steps: Step[] =
799	    capturePosition === 'start'
800	      ? [{ kind: 'capture', index: 0 }]
801	      : [{ kind: 'intro', index: 0 }];
802	  questions.forEach((_, i) => steps.push({ kind: 'question', index: i }));
803	  if (capturePosition === 'end') steps.push({ kind: 'capture', index: 0 });
804	  return steps;
805	}
806	
807	/**
808	 * Returns the questions in the order they should be presented to the user,
809	 * based on `quiz.randomize`. Section order from the frontmatter is always
810	 * preserved; only the within-section order can be shuffled. Questions that
811	 * belong to no declared section are appended at the end in their original
812	 * order.
813	 */
814	function orderQuestions(quiz: QuizData): QuizQuestion[] {
815	  if (quiz.randomize !== 'within-sections') return quiz.questions;
816	
817	  const bySection = new Map<string, QuizQuestion[]>();
818	  const orphans: QuizQuestion[] = [];
819	  const knownSectionIds = new Set(quiz.sections.map((s) => s.id));
820	  for (const q of quiz.questions) {
821	    if (!knownSectionIds.has(q.section)) {
822	      orphans.push(q);
823	      continue;
824	    }
825	    const bucket = bySection.get(q.section) ?? [];
826	    bucket.push(q);
827	    bySection.set(q.section, bucket);
828	  }
829	
830	  const out: QuizQuestion[] = [];
831	  for (const section of quiz.sections) {
832	    const bucket = bySection.get(section.id);
833	    if (!bucket) continue;
834	    out.push(...shuffle(bucket));
835	  }
836	  out.push(...orphans);
837	  return out;
838	}
839	
840	/**
841	 * Builds the per-question option display order. When `randomizeOptions` is
842	 * `'shuffle'`, each question's option indices are shuffled; otherwise the
843	 * declared order is kept. Returns a map of question id → original option
844	 * indices in the order they should be shown.
845	 */
846	function buildOptionOrder(quiz: QuizData): Record<string, number[]> {
847	  const order: Record<string, number[]> = {};
848	  const shuffleOptions = quiz.randomizeOptions === 'shuffle';
849	  for (const question of quiz.questions) {
850	    const indices = question.options.map((_, i) => i);
851	    order[question.id] = shuffleOptions ? shuffle(indices) : indices;
852	  }
853	  return order;
854	}
855	
856	function shuffle<T>(items: T[]): T[] {
857	  const out = items.slice();
858	  for (let i = out.length - 1; i > 0; i--) {
859	    const j = Math.floor(Math.random() * (i + 1));
860	    [out[i], out[j]] = [out[j], out[i]];
861	  }
862	  return out;
863	}
864	
865	function computeProgress(
866	  step: Step,
867	  steps: Step[],
868	  capturePosition: CapturePosition
869	): { current: number; total: number } {
870	  const questionSteps = steps.filter((s) => s.kind === 'question').length;
871	  if (step.kind === 'intro') return { current: 0, total: questionSteps };
872	  // A start-gate capture sits before question 1, so it is 0% done, not 100%.
873	  if (step.kind === 'capture') {
874	    return {
875	      current: capturePosition === 'start' ? 0 : questionSteps,
876	      total: questionSteps,
877	    };
878	  }
879	  return { current: step.index + 1, total: questionSteps };
880	}
881	
882	function CorrectIcon() {
883	  return (
884	    <svg
885	      className="text-quiz-valuable-strong size-5 shrink-0"
886	      viewBox="0 0 20 20"
887	      fill="currentColor"
888	      aria-label="Correct"
889	      role="img"
890	    >
891	      <path
892	        fillRule="evenodd"
893	        clipRule="evenodd"
894	        d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16zm3.857-9.809a.75.75 0 0 0-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 1 0-1.06 1.061l2.5 2.5a.75.75 0 0 0 1.137-.089l4-5.5z"
895	      />
896	    </svg>
897	  );
898	}
899	
