import { useEffect, useRef, useState } from 'react';
import { buildResultQuery, computeQuizResult } from '../scoring';
import { buildMapMoveQuery, computeMapMove } from '../map-move';
import type {
  CapturePosition,
  QuizData,
  QuizQuestion,
  QuizResponses,
} from '../types';
import QuizIntroCard from './QuizIntroCard';

// One primary button style, shared by every step. Near-black, flat, no shadow:
// the design reserves colour for meaning, so the buttons stay neutral.
const PRIMARY_BUTTON =
  'rounded-lg bg-quiz-ink px-5 py-2.5 text-base font-medium text-white transition hover:opacity-90 focus:outline-none focus:ring-2 focus:ring-quiz-accent-strong focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-40';

export interface QuizStepperProps {
  quiz: QuizData;
  /**
   * Cakemail hosted-form submission URL (the `action` of a Cakemail-rendered
   * form). The stepper POSTs `email`, `custom_attributes[firstname]`, and any
   * `submissionTags` / level tag as multipart form-data; Cakemail handles list
   * add and double opt-in. Quiz scoring happens in the browser, so the redirect
   * URL is built locally and the user lands on the results page regardless of
   * Cakemail's response.
   *
   * Optional: provide EITHER `cakemailFormUrl` (built-in best-effort POST) OR
   * `onSubmit` (host owns delivery). If both are given, `onSubmit` wins.
   */
  cakemailFormUrl?: string;
  /**
   * Override for how the captured contact is delivered. Receives the multipart
   * form-data the engine assembled (email, firstname, tags). Use it to route the
   * submission through your own endpoint (e.g. a CAPTCHA-gated proxy) instead of
   * POSTing straight to Cakemail. Unlike the built-in POST, this hook is
   * authoritative: if it throws, the engine shows the thrown message and keeps
   * the user on the capture step (no redirect) so they can retry. Resolve to
   * proceed.
   */
  onSubmit?: (formData: FormData) => Promise<void>;
  /**
   * Extra content rendered inside the capture form, just above the submit button.
   * Use it to mount a pre-submit widget the host needs at submit time (e.g. a
   * CAPTCHA whose token your `onSubmit` reads). The engine treats it as opaque.
   */
  captureExtras?: React.ReactNode;
  /**
   * Required. Used to build the results redirect path (`/quiz/{slug}/results/?...`).
   */
  quizSlug: string;
  introTitle?: string;
  introBody?: string;
  /** Icon in the intro card's chip. Defaults to the privacy icon. */
  introIcon?: string;
  startButtonLabel?: string;
  /**
   * Label on the button that finishes the quiz and goes to the results page.
   * With `capturePosition: 'end'` that is the capture form's submit button; with
   * `'start'` it is the last question's "next" button.
   */
  submitButtonLabel?: string;
  showCorrectness?: boolean;
  /** Heading above the capture form. Defaults to wording that suits the position. */
  captureHeading?: string;
  /**
   * Body copy under the capture heading. Shown only by the end-of-quiz capture
   * card; the start gate is a compact panel with no room for a paragraph.
   */
  captureBody?: string;
  /**
   * Label on the capture form's own button. Defaults to `submitButtonLabel` at
   * the end of a quiz and to `startButtonLabel` on a start gate, since that
   * button leads to question 1 rather than to the result.
   */
  captureButtonLabel?: string;
  /**
   * Small print shown under the submit button on the capture step. Use it to
   * tell the user what they're opting into (e.g. "You'll also receive ...").
   */
  captureFootnote?: string;
  /**
   * Tags applied to the contact on submission, sent as Cakemail's
   * `tags[<name>]=true` form fields. Use for audience segmentation that the
   * email platform's automations can trigger on (e.g. ['aiquiz']).
   */
  submissionTags?: string[];
  /**
   * When set, the contact is also tagged with `${levelTagPrefix}${overallLevel}`
   * (e.g. prefix 'aiquiz-' + level 'high-risk' => tag 'aiquiz-high-risk'), so a
   * nurture sequence can branch on the quiz result tier. Ignored on a start
   * gate, where nothing has been answered yet.
   */
  levelTagPrefix?: string;
}

type StepKind = 'intro' | 'question' | 'capture';

interface Step {
  kind: StepKind;
  index: number;
}

export default function QuizStepper({
  quiz,
  cakemailFormUrl,
  onSubmit,
  captureExtras,
  quizSlug,
  introTitle,
  introBody,
  introIcon = 'privacy',
  startButtonLabel = 'Start the quiz',
  submitButtonLabel = 'See my results',
  showCorrectness = false,
  captureHeading,
  captureBody,
  captureButtonLabel,
  captureFootnote = "You'll also be subscribed to our list. You can unsubscribe at any time.",
  submissionTags,
  levelTagPrefix,
}: QuizStepperProps) {
  const capturePosition = quiz.capturePosition ?? 'end';
  // Order questions once on mount. Shuffling lives inside a `useState`
  // initializer so each user gets a stable order across re-renders and
  // back-button navigation. Section order is always preserved.
  const [orderedQuestions] = useState<QuizQuestion[]>(() =>
    orderQuestions(quiz)
  );
  // Per-question option display order (arrays of original option indices).
  // Computed once on mount so a shuffled order stays stable across re-renders
  // and back-navigation. Scoring stores the original index, not the display
  // position, so shuffling never affects results.
  const [optionOrder] = useState<Record<string, number[]>>(() =>
    buildOptionOrder(quiz)
  );
  const steps = buildSteps(orderedQuestions, capturePosition);
  const [stepIndex, setStepIndex] = useState(0);
  const [responses, setResponses] = useState<QuizResponses>({});
  const [revealed, setRevealed] = useState<Record<string, boolean>>({});
  const [firstName, setFirstName] = useState('');
  const [email, setEmail] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  // True once the contact has been delivered. Only meaningful for a start gate,
  // where the back button can bring the taker back to an already-submitted
  // capture form; without this the second click would POST the same contact again.
  const [captured, setCaptured] = useState(false);
  const initialised = useRef(false);
  const startedRef = useRef(false);

  useEffect(() => {
    if (initialised.current) return;
    initialised.current = true;
    window.history.replaceState({ quizStep: 0 }, '');

    const onPop = (event: PopStateEvent) => {
      const next = event.state?.quizStep;
      if (typeof next === 'number' && next >= 0 && next < steps.length) {
        setStepIndex(next);
      }
    };
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, [steps.length]);

  // Fire a generic event whenever the step changes so the host page can react
  // (e.g. hide marketing chrome once the quiz is underway). The engine has no
  // opinion about what consumers do with this. `quiz:started` is a one-shot
  // event the first time a question appears, intended for analytics.
  useEffect(() => {
    const step = steps[stepIndex];
    window.dispatchEvent(
      new CustomEvent('quiz:step-changed', {
        detail: { kind: step.kind, index: stepIndex },
      })
    );
    if (!startedRef.current && step.kind === 'question') {
      startedRef.current = true;
      window.dispatchEvent(new CustomEvent('quiz:started'));
    }
  }, [stepIndex, steps]);

  const goToStep = (next: number) => {
    if (next < 0 || next >= steps.length) return;
    window.history.pushState({ quizStep: next }, '');
    setStepIndex(next);
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  // Listen for a `quiz:start-requested` event so a host page can trigger the
  // quiz from its own chrome (e.g. a marketing hero "Start the Quiz" button).
  // No-op unless currently on the first step, so duplicate dispatches are safe.
  useEffect(() => {
    const onStartRequested = () => {
      if (stepIndex === 0) goToStep(1);
    };
    window.addEventListener('quiz:start-requested', onStartRequested);
    return () =>
      window.removeEventListener('quiz:start-requested', onStartRequested);
  }, [stepIndex, steps]);

  const step = steps[stepIndex];
  const progress = computeProgress(step, steps, capturePosition);

  // Score the quiz in the browser so the results URL is ready without a round
  // trip. Doing it client-side also means the taker lands on the results page
  // even if the ESP rejects the submission — they finished the quiz, they get
  // the result. The query shape depends on the result style: band carries
  // scores/levels; map-move carries the raw answers so the (stateless) results
  // page can rebuild the map.
  const scoreQuiz = (): { query: URLSearchParams; level: string } => {
    if (quiz.resultStyle === 'map-move') {
      return {
        query: buildMapMoveQuery(quiz, responses),
        level: computeMapMove(quiz, responses).framing ?? '',
      };
    }
    const result = computeQuizResult(quiz, responses);
    return { query: buildResultQuery(result), level: result.overallLevel };
  };

  const goToResults = () => {
    const { query } = scoreQuiz();
    window.location.href = `/quiz/${quizSlug}/results/?${query.toString()}`;
  };

  if (step.kind === 'intro') {
    return (
      <Shell progress={progress} showProgress={false}>
        <QuizIntroCard
          title={introTitle ?? quiz.title}
          body={introBody ?? quiz.intro}
          icon={introIcon}
          buttonLabel={startButtonLabel}
          onStart={() => goToStep(stepIndex + 1)}
        />
      </Shell>
    );
  }

  if (step.kind === 'question') {
    const question = orderedQuestions[step.index];
    const chosenIndex = responses[question.id];
    const isRevealed = !!revealed[question.id];

    const onPick = (optionIndex: number) => {
      setResponses((prev) => ({ ...prev, [question.id]: optionIndex }));
      setRevealed((prev) => ({ ...prev, [question.id]: true }));
    };

    // On a start gate the capture step is already behind the taker, so the last
    // question is the end of the quiz: its "next" button goes to the results.
    const finishesQuiz = stepIndex === steps.length - 1;

    return (
      <Shell progress={progress} showProgress>
        <QuestionScreen
          quiz={quiz}
          question={question}
          optionOrder={optionOrder[question.id]}
          chosenIndex={chosenIndex}
          revealed={isRevealed}
          showCorrectness={showCorrectness}
          onPick={onPick}
          nextLabel={finishesQuiz ? submitButtonLabel : 'Next'}
          onNext={finishesQuiz ? goToResults : () => goToStep(stepIndex + 1)}
        />
      </Shell>
    );
  }

  // capture step
  // A start gate runs before question 1, so there is nothing to have answered.
  const allAnswered =
    capturePosition === 'start' ||
    quiz.questions.every((q) => q.id in responses);

  const handleSubmit = async (e: React.SyntheticEvent) => {
    e.preventDefault();
    if (submitting) return;

    // Back-navigated onto an already-submitted start gate: just move on rather
    // than delivering the same contact a second time.
    if (captured) {
      goToStep(stepIndex + 1);
      return;
    }

    setSubmitError(null);
    setSubmitting(true);

    // Only an end capture has answers to score and a result tier to tag with.
    const scored = capturePosition === 'end' ? scoreQuiz() : null;

    const formData = new FormData();
    formData.append('email', email.trim());
    if (firstName.trim()) {
      formData.append('custom_attributes[firstname]', firstName.trim());
    }
    // Cakemail tags use a dict shape: `tags[<name>]=true`. Static tags from the
    // host plus an optional result-tier tag drive the nurture sequence.
    for (const tag of submissionTags ?? []) {
      formData.append(`tags[${tag}]`, 'true');
    }
    if (levelTagPrefix && scored?.level) {
      formData.append(`tags[${levelTagPrefix}${scored.level}]`, 'true');
    }

    // Host-provided delivery wins and is authoritative: if it throws (e.g. a
    // CAPTCHA gate rejects the submission), surface the message and keep the user
    // on the capture step so they can retry — don't move on.
    if (onSubmit) {
      try {
        await onSubmit(formData);
      } catch (err) {
        setSubmitError(
          err instanceof Error
            ? err.message
            : 'Something went wrong. Please try again.'
        );
        setSubmitting(false);
        return;
      }
    } else if (cakemailFormUrl) {
      try {
        // `no-cors` fires the POST without requiring Cakemail to send back
        // CORS headers. We can't read the response, but for a marketing-form
        // submission we don't need to — Cakemail's double opt-in email is the
        // user's source of truth, not our success/error state.
        await fetch(cakemailFormUrl, {
          method: 'POST',
          mode: 'no-cors',
          body: formData,
        });
      } catch (err) {
        // Network failure only. Log so a real outage shows up in PostHog/console,
        // but still send the user on — they earned their result.
        console.error('quiz signup POST failed', err);
      }
    }

    setCaptured(true);

    // An end capture is the last step, so send the taker to their results. A
    // start gate hands off to the intro instead.
    if (scored) {
      window.location.href = `/quiz/${quizSlug}/results/?${scored.query.toString()}`;
      return;
    }
    setSubmitting(false);
    goToStep(stepIndex + 1);
  };

  const captureProps = {
    email,
    onEmailChange: setEmail,
    onSubmit: handleSubmit,
    submitting,
    canSubmit: allAnswered && email.includes('@'),
    // A start gate's button begins the questions, so it falls back to the
    // "start" label, not the "finish" one: promising the result on a button
    // that leads to question 1 is a lie the taker notices immediately.
    submitButtonLabel:
      captureButtonLabel ??
      (capturePosition === 'start' ? startButtonLabel : submitButtonLabel),
    footnote: captureFootnote,
    error: submitError,
    extras: captureExtras,
  };

  // The start gate is a compact panel that sits inside the cover's own layout;
  // the end capture is a standalone card at the finish of the quiz.
  if (capturePosition === 'start') {
    return (
      <CapturePanel
        {...captureProps}
        heading={captureHeading ?? 'Where should I send your result?'}
      />
    );
  }

  return (
    <Shell progress={progress} showProgress>
      <CaptureCard
        {...captureProps}
        heading={captureHeading ?? 'Where should we send your results?'}
        body={
          captureBody ??
          "Enter your email and we'll show you your results and what they mean."
        }
        firstName={firstName}
        onFirstNameChange={setFirstName}
      />
    </Shell>
  );
}

function Shell({
  progress,
  showProgress,
  children,
}: {
  progress: { current: number; total: number };
  showProgress: boolean;
  children: React.ReactNode;
}) {
  const pct = Math.round((progress.current / progress.total) * 100);
  return (
    <div className="quiz-stepper mx-auto w-full max-w-170">
      {showProgress ? (
        <div className="mb-6">
          <div className="text-quiz-ink-muted mb-1.5 flex items-center justify-between text-sm">
            <span>
              Step {progress.current} of {progress.total}
            </span>
            <span>{pct}%</span>
          </div>
          <div className="bg-quiz-hairline h-1.5 w-full overflow-hidden rounded-full">
            <div
              className="bg-quiz-accent-strong h-full transition-all duration-300"
              style={{ width: `${pct}%` }}
              role="progressbar"
              aria-valuenow={pct}
              aria-valuemin={0}
              aria-valuemax={100}
            />
          </div>
        </div>
      ) : null}
      {children}
    </div>
  );
}

function QuestionScreen({
  quiz,
  question,
  optionOrder,
  chosenIndex,
  revealed,
  showCorrectness,
  onPick,
  nextLabel,
  onNext,
}: {
  quiz: QuizData;
  question: QuizQuestion;
  /** Original option indices in display order; defaults to declared order. */
  optionOrder?: number[];
  chosenIndex: number | undefined;
  revealed: boolean;
  showCorrectness: boolean;
  onPick: (optionIndex: number) => void;
  /** "Next" for every question but the last one of a start-gated quiz. */
  nextLabel: string;
  onNext: () => void;
}) {
  const section = quiz.sections.find((s) => s.id === question.section);
  const maxOptionScore = Math.max(...question.options.map((o) => o.score));
  const userGotItRight =
    revealed &&
    chosenIndex !== undefined &&
    question.options[chosenIndex]?.score === maxOptionScore;
  const order = optionOrder ?? question.options.map((_, i) => i);
  // An answer locks only when picking it disclosed something the taker could
  // now act on: a quiz that marks answers right or wrong, or a question with
  // reveal copy. A reflective question discloses nothing, so let them change
  // their mind, which is the point of asking someone to think back over a
  // couple of sprints. They can also come back and change it with the back
  // button, since responses are keyed by question id.
  const answerLocked = revealed && (showCorrectness || !!question.reveal);

  return (
    <div className="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-6 md:p-8">
      {section ? (
        <p className="text-quiz-accent-strong mb-2 text-sm">{section.label}</p>
      ) : null}
      <h2 className="text-quiz-ink mb-6 text-2xl font-bold md:text-3xl">
        {question.text}
      </h2>
      <ul className="space-y-2.5">
        {order.map((originalIndex, displayIndex) => {
          const option = question.options[originalIndex];
          if (!option) return null;
          const isChosen = chosenIndex === originalIndex;
          // The chip letter follows the *display* position, never the authored
          // one. With `randomizeOptions: 'shuffle'` the authored letter would
          // both come out jumbled (b, d, a, c) and leak the authoring pattern,
          // e.g. that "d" is always the context answer. It is a visual anchor
          // for the eye, carrying no meaning of its own.
          const letter = String.fromCharCode(97 + displayIndex);
          const isCorrect = showCorrectness && option.score === maxOptionScore;
          const showAsCorrectPick = revealed && isCorrect && userGotItRight;
          const showAsCorrectAnswer = revealed && isCorrect && !userGotItRight;
          // Only mark a pick "wrong" when the quiz scores answers. Reflective
          // quizzes (showCorrectness=false) have no wrong answer, so a chosen
          // option just reads as selected.
          const showAsWrong =
            showCorrectness && revealed && isChosen && !isCorrect;
          // Every option carries a 2px border and only the colour changes with
          // state. Selection needs the heavier weight to read, and swapping the
          // width instead would jog each tile by 3px as it is picked.
          let optionClasses =
            'w-full rounded-lg border-2 px-4 py-3 text-left text-base leading-snug transition focus:outline-none focus:ring-2 focus:ring-quiz-accent-strong focus:ring-offset-2';
          let chipClasses = 'bg-quiz-context-panel text-quiz-ink-muted';
          if (showAsCorrectPick) {
            optionClasses +=
              ' border-quiz-valuable-edge bg-quiz-valuable-tint text-quiz-ink';
            chipClasses = 'bg-quiz-valuable-strong text-white';
          } else if (showAsCorrectAnswer) {
            // Outline only, so it reads as a reference rather than a celebration.
            optionClasses +=
              ' border-quiz-valuable-edge bg-quiz-card text-quiz-ink';
            chipClasses = 'bg-quiz-valuable-tint text-quiz-valuable-strong';
          } else if (showAsWrong) {
            optionClasses +=
              ' border-quiz-slipping-edge bg-quiz-slipping-tint text-quiz-ink';
            chipClasses = 'bg-quiz-slipping-strong text-white';
          } else if (isChosen) {
            optionClasses +=
              ' border-quiz-accent-edge bg-quiz-accent-tint text-quiz-ink';
            chipClasses = 'bg-quiz-accent-strong text-white';
          } else if (answerLocked) {
            // The answer is settled, so mute what wasn't picked.
            optionClasses +=
              ' border-quiz-hairline bg-quiz-card text-quiz-ink-muted';
          } else {
            // Still changeable: keep the hover so it stays obviously pickable.
            optionClasses +=
              ' border-quiz-hairline bg-quiz-card text-quiz-ink hover:border-quiz-accent-edge hover:bg-quiz-accent-tint';
          }
          return (
            <li key={originalIndex}>
              <button
                type="button"
                onClick={() => !answerLocked && onPick(originalIndex)}
                disabled={answerLocked}
                className={`${optionClasses} flex items-start gap-3`}
                aria-pressed={isChosen}
              >
                <span
                  className={`flex size-6 shrink-0 items-center justify-center rounded-md text-sm font-medium transition ${chipClasses}`}
                  aria-hidden="true"
                >
                  {letter}
                </span>
                <span className="flex-1">{option.text}</span>
                {showAsCorrectPick ? (
                  <CorrectIcon />
                ) : showAsWrong ? (
                  <WrongIcon />
                ) : null}
              </button>
            </li>
          );
        })}
      </ul>

      {revealed && question.reveal ? (
        <div
          className="bg-quiz-context-panel text-quiz-ink-secondary mt-6 rounded-xl p-4 text-base/relaxed"
          role="status"
          aria-live="polite"
        >
          <p className="whitespace-pre-line">
            {renderInlineMarkdown(question.reveal)}
          </p>
        </div>
      ) : null}

      {revealed ? (
        <div className="mt-6 flex justify-end">
          <button type="button" onClick={onNext} className={PRIMARY_BUTTON}>
            {nextLabel}
          </button>
        </div>
      ) : null}
    </div>
  );
}

