// Minimal inline markdown: only `[label](url)` links. Kept inline so the
// engine has no markdown dependency when extracted.
function renderInlineMarkdown(text: string): React.ReactNode[] {
  const nodes: React.ReactNode[] = [];
  const linkRegex = /\[([^\]]+)\]\(([^)\s]+)\)/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let key = 0;
  while ((match = linkRegex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }
    const [, label, url] = match;
    const isExternal = /^https?:\/\//i.test(url);
    nodes.push(
      <a
        key={key++}
        href={url}
        {...(isExternal
          ? { target: '_blank', rel: 'noopener noreferrer' }
          : {})}
        className="text-quiz-accent-strong underline"
      >
        {label}
      </a>
    );
    lastIndex = linkRegex.lastIndex;
  }
  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }
  return nodes.length > 0 ? nodes : [text];
}

/**
 * The step order. The first step is the one the host page's marketing chrome
 * sits alongside.
 *
 * A start gate has no intro *step*: the cover is already the place to reassure
 * someone, and it has to happen before they hand over an email, not after. The
 * host page renders `QuizIntroCard` under the opt-in instead, so the gate's
 * button is the cover's only action and submitting it goes straight to
 * question 1.
 */
function buildSteps(
  questions: QuizQuestion[],
  capturePosition: CapturePosition
): Step[] {
  const steps: Step[] =
    capturePosition === 'start'
      ? [{ kind: 'capture', index: 0 }]
      : [{ kind: 'intro', index: 0 }];
  questions.forEach((_, i) => steps.push({ kind: 'question', index: i }));
  if (capturePosition === 'end') steps.push({ kind: 'capture', index: 0 });
  return steps;
}

/**
 * Returns the questions in the order they should be presented to the user,
 * based on `quiz.randomize`. Section order from the frontmatter is always
 * preserved; only the within-section order can be shuffled. Questions that
 * belong to no declared section are appended at the end in their original
 * order.
 */
function orderQuestions(quiz: QuizData): QuizQuestion[] {
  if (quiz.randomize !== 'within-sections') return quiz.questions;

  const bySection = new Map<string, QuizQuestion[]>();
  const orphans: QuizQuestion[] = [];
  const knownSectionIds = new Set(quiz.sections.map((s) => s.id));
  for (const q of quiz.questions) {
    if (!knownSectionIds.has(q.section)) {
      orphans.push(q);
      continue;
    }
    const bucket = bySection.get(q.section) ?? [];
    bucket.push(q);
    bySection.set(q.section, bucket);
  }

  const out: QuizQuestion[] = [];
  for (const section of quiz.sections) {
    const bucket = bySection.get(section.id);
    if (!bucket) continue;
    out.push(...shuffle(bucket));
  }
  out.push(...orphans);
  return out;
}

/**
 * Builds the per-question option display order. When `randomizeOptions` is
 * `'shuffle'`, each question's option indices are shuffled; otherwise the
 * declared order is kept. Returns a map of question id → original option
 * indices in the order they should be shown.
 */
function buildOptionOrder(quiz: QuizData): Record<string, number[]> {
  const order: Record<string, number[]> = {};
  const shuffleOptions = quiz.randomizeOptions === 'shuffle';
  for (const question of quiz.questions) {
    const indices = question.options.map((_, i) => i);
    order[question.id] = shuffleOptions ? shuffle(indices) : indices;
  }
  return order;
}

function shuffle<T>(items: T[]): T[] {
  const out = items.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

function computeProgress(
  step: Step,
  steps: Step[],
  capturePosition: CapturePosition
): { current: number; total: number } {
  const questionSteps = steps.filter((s) => s.kind === 'question').length;
  if (step.kind === 'intro') return { current: 0, total: questionSteps };
  // A start-gate capture sits before question 1, so it is 0% done, not 100%.
  if (step.kind === 'capture') {
    return {
      current: capturePosition === 'start' ? 0 : questionSteps,
      total: questionSteps,
    };
  }
  return { current: step.index + 1, total: questionSteps };
}

