            .enum(['accent', 'valuable', 'slipping', 'alt'])
            .default('accent'),
        })
      )
      .optional(),
    sections: z
      .array(
        z.object({
          id: z.string(),
          label: z.string(),
          blurb: z.string().optional(),
          image: image().or(z.string()).optional(),
        })
      )
      .min(1),
    questions: z
      .array(
        z.object({
          id: z.string(),
          section: z.string(),
          text: z.string(),
          reveal: z.string().optional(),
