import type {
  QuizData,
  QuizLevelThreshold,
  QuizResponses,
  QuizResult,
} from './types';

export function getOptionScore(
  quiz: QuizData,
  questionId: string,
  optionIndex: number
): number {
  const question = quiz.questions.find((q) => q.id === questionId);
  if (!question) return 0;
  const option = question.options[optionIndex];
  if (!option) return 0;
  return option.score;
}

export function getMaxQuestionScore(
  quiz: QuizData,
  questionId: string
): number {
  const question = quiz.questions.find((q) => q.id === questionId);
  if (!question) return 0;
  return Math.max(...question.options.map((o) => o.score));
}

export function findLevel(
  score: number,
  thresholds: QuizLevelThreshold[]
): QuizLevelThreshold | null {
  for (const t of thresholds) {
    if (score >= t.minScore && score <= t.maxScore) return t;
  }
  return null;
}

export function computeQuizResult(
  quiz: QuizData,
  responses: QuizResponses
): QuizResult {
  const sectionScores: Record<string, number> = {};
  const sectionMaxScores: Record<string, number> = {};
  for (const section of quiz.sections) {
    sectionScores[section.id] = 0;
    sectionMaxScores[section.id] = 0;
  }

  let total = 0;
  let maxTotal = 0;

  for (const question of quiz.questions) {
    const maxForQuestion = getMaxQuestionScore(quiz, question.id);
    maxTotal += maxForQuestion;
    if (sectionMaxScores[question.section] !== undefined) {
      sectionMaxScores[question.section] += maxForQuestion;
    }
    const chosenIndex = responses[question.id];
    if (chosenIndex === undefined) continue;
    const score = getOptionScore(quiz, question.id, chosenIndex);
    total += score;
    if (sectionScores[question.section] !== undefined) {
      sectionScores[question.section] += score;
    }
  }

  const sectionLevels: Record<string, string> = {};
  for (const section of quiz.sections) {
    const matched = findLevel(
      sectionScores[section.id],
      quiz.sectionLevels ?? []
    );
    if (matched) sectionLevels[section.id] = matched.level;
  }

  const overall = findLevel(total, quiz.overallLevels ?? []);

  return {
    total,
    maxTotal,
    sectionScores,
    sectionLevels,
    overallLevel: overall?.level ?? '',
    overallTitle: overall?.title,
  };
}

/**
 * Produces the URL query string used to render a stateless results page.
 * Includes the overall total, the overall level, and one entry per section
 * (section id → level).
 */
export function buildResultQuery(result: QuizResult): URLSearchParams {
  const params = new URLSearchParams();
  params.set('total', String(result.total));
  params.set('max', String(result.maxTotal));
  params.set('level', result.overallLevel);
  for (const [sectionId, level] of Object.entries(result.sectionLevels)) {
    params.set(sectionId, level);
  }
  return params;
}

