// Drive the real quiz in a browser: answer the profile question as Manager,
// then walk the eight questions and check progress + lens behaviour.
import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage();
const errs = [];
p.on('pageerror', e => errs.push(String(e)));
p.on('console', m => { if (m.type() === 'error') errs.push(m.text()); });
await p.goto('http://localhost:4321/quiz/scrum-master-ai/', { waitUntil: 'networkidle' });

await p.getByRole('button', { name: 'Start the quiz' }).first().click();
await p.waitForTimeout(400);
// step 0 = intro card
await p.getByRole('button', { name: /Start the quiz|Begin/i }).first().click();
await p.waitForTimeout(400);

const h = await p.locator('h2').first().innerText();
console.log('PROFILE Q:', h);
console.log('progress bar on profile step:', await p.locator('[role=progressbar]').count());

// pick the Manager option
await p.getByRole('button', { name: /I manage the Scrum Master/ }).click();
await p.waitForTimeout(300);
console.log('lens shown on profile step:', (await p.locator('text=/think about where your Scrum Master spent their time/').count()) > 0);

for (let i = 1; i <= 8; i++) {
  await p.getByRole('button', { name: 'Next' }).click();
  await p.waitForTimeout(250);
  const step = await p.locator('text=/^Step \\d+ of \\d+$/').first().innerText().catch(() => 'NONE');
  const lens = await p.locator('text=/think about where your Scrum Master spent their time/').count();
  console.log(`q${i}: ${step} | lens visible: ${lens > 0}`);
  await p.locator('ul li button').first().click();
  await p.waitForTimeout(150);
}
await p.getByRole('button', { name: /Show me my map/i }).first().click();
await p.waitForTimeout(400);
console.log('capture heading:', await p.locator('h2').first().innerText());
console.log('PAGE ERRORS:', errs.length ? errs : 'none');
await b.close();
EOF
