// Verifies the profile-question rules against the real quiz's shape.
import { computeMapMove, computeQuizResult } from '../Users/marklevison/Documents/GitHub/APR/agile-pain-relief-astro/src/lib/quiz-engine/index.ts';
import type { QuizData } from '../Users/marklevison/Documents/GitHub/APR/agile-pain-relief-astro/src/lib/quiz-engine/index.ts';

const quiz: QuizData = {
  title: 't',
  resultStyle: 'map-move',
  sections: [{ id: 'time', label: 'Time' }],
  questions: [
    {
      id: 'role', section: 'profile', kind: 'profile', text: 'role?',
      options: [
        { text: 'SM', score: 0, tag: 'role-scrum-master' },
        { text: 'Mgr', score: 0, tag: 'role-manager', lens: 'answer for your SM' },
      ],
    },
    {
      id: 'q1', section: 'time', text: 'q1?',
      options: [
        { text: 'bad', score: 0, bucket: 'slipping', mapSentence: 'slip', reclaimSentence: 'r' },
        { text: 'good', score: 2, bucket: 'gaining', mapSentence: 'gain' },
      ],
    },
  ],
  mapMove: {
    reclaimPriority: ['q1'], redirectPriority: ['q1'],
    gainingHeading: 'g', slippingHeading: 's',
  },
};

// Manager (profile idx 1) + slipping answer on q1.
const responses = { role: 1, q1: 0 };
const map = computeMapMove(quiz, responses);
const scored = computeQuizResult(quiz, responses);

const checks: [string, boolean][] = [
  ['profile answer not in gaining/slipping/context',
    [...map.gaining, ...map.slipping, ...map.context].every(e => e.questionId !== 'role')],
  ['slipping still picked up', map.slipping.length === 1],
  ['balance bar sees only the scored answer', map.gaining.length + map.slipping.length === 1],
  ['maxTotal excludes profile (2, not 2+0)', scored.maxTotal === 2],
  ['total excludes profile', scored.total === 0],
];
// A profile question would previously have contributed a `mixed` entry and, if
// bucketed context, an empty row. Confirm neither happens.
for (const [name, ok] of checks) console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}`);
process.exit(checks.every(([, ok]) => ok) ? 0 : 1);
EOF
