import pw from '/Users/marklevison/Documents/GitHub/APR/social-media-posting/node_modules/playwright-core/index.js';
const { chromium } = pw;
const LENS = /think about where your Scrum Master spent their time/;

async function walk(roleLabel, expectLens) {
  const b = await chromium.launch();
  const p = await b.newPage();
  const errs = [];
  p.on('pageerror', e => errs.push(String(e)));
  p.on('console', m => { if (m.type() === 'error' && !/favicon/.test(m.text())) errs.push(m.text()); });
  await p.goto('http://localhost:4321/quiz/scrum-master-ai/', { waitUntil: 'networkidle' });
  await p.waitForTimeout(600);
  await p.getByRole('button', { name: 'Start the quiz' }).first().click();
  await p.waitForTimeout(500);

  const out = [];
  out.push(['profile step shows no progress bar', (await p.locator('[role=progressbar]').count()) === 0]);
  await p.getByRole('button', { name: roleLabel }).click();
  await p.waitForTimeout(300);
  out.push([`lens visible on profile step itself = ${expectLens}`,
    ((await p.locator('.quiz-stepper').innerText()).match(LENS) !== null) === expectLens]);

  const steps = [];
  for (let i = 1; i <= 8; i++) {
    await p.getByRole('button', { name: 'Next' }).click();
    await p.waitForTimeout(220);
    const txt = await p.locator('.quiz-stepper').innerText();
    steps.push((txt.match(/Step (\d+) of (\d+)/) || [])[0] || 'NO-PROGRESS');
    out.push([`q${i} lens = ${expectLens}`, (txt.match(LENS) !== null) === expectLens]);
    await p.locator('.quiz-stepper ul li button').first().click();
    await p.waitForTimeout(150);
  }
  out.push(['progress runs 1..8 of 8', steps.join('|') ===
    'Step 1 of 8|Step 2 of 8|Step 3 of 8|Step 4 of 8|Step 5 of 8|Step 6 of 8|Step 7 of 8|Step 8 of 8']);

  await p.getByRole('button', { name: /Show me my map/i }).first().click();
  await p.waitForTimeout(500);
  const capture = await p.locator('.quiz-stepper').innerText();
  out.push(['reaches capture card', /Where should I send your result/.test(capture)]);
  out.push(['no lens leaking onto the capture card', !LENS.test(capture)]);

  console.log(`\n--- ${roleLabel} ---`);
  console.log('progress:', steps.join(' | '));
  for (const [name, ok] of out) console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}`);
  if (errs.length) console.log('PAGE ERRORS:', errs.slice(0, 4));
  await b.close();
  return out.every(([, ok]) => ok) && errs.length === 0;
}

const a = await walk(/I manage the Scrum Master/, true);
const c = await walk(/It’s the job I’m hired to do/, false);
console.log(a && c ? '\nALL PASS' : '\nFAILURES ABOVE');
process.exit(a && c ? 0 : 1);
EOF
