    const optionIndex = responses[question.id];
    if (optionIndex === undefined) continue;
    pairs.push(`${question.id}-${optionIndex}`);
  }
  params.set('a', pairs.join('.'));
  return params;
}

export function parseMapMoveResponses(params: URLSearchParams): QuizResponses {
  const responses: QuizResponses = {};
  const raw = params.get('a');
  if (!raw) return responses;
  for (const pair of raw.split('.')) {
    const sep = pair.lastIndexOf('-');
    if (sep <= 0) continue;
    const id = pair.slice(0, sep);
    const index = parseInt(pair.slice(sep + 1), 10);
    if (id && Number.isInteger(index) && index >= 0) responses[id] = index;
