export type MapMoveBucket = 'gaining' | 'mixed' | 'slipping' | 'context';

export interface QuizOption {
  text: string;
  score: number;
  /**
   * Concept icon shown beside this answer's sentence in the map (see
   * `QuizIcon`'s vocabulary). Reinforces the colour, never carries meaning alone.
   */
  icon?: string;
  /**
   * map-move classification for this answer. `'context'` marks a real-world
   * constraint that must not be scored as a gap. Ignored by the band style.
   */
  bucket?: MapMoveBucket;
  /** Line shown for this answer in the map (gaining/slipping column or context notes). */
  mapSentence?: string;
  /** Shown when this answer is chosen as the reclaim target of the one move. */
  reclaimSentence?: string;
  /** Shown when this answer is chosen as the redirect target of the one move. */
  redirectSentence?: string;
  /**
   * Tag applied to the submission when this answer is chosen, sent alongside
   * the host's static tags as `tags[<name>]=true`. Use on a `profile` question
   * to segment the list by who the taker is.
   */
  tag?: string;
  /**
   * A standing instruction for the rest of the quiz, shown from the moment this
   * answer is chosen and repeated above every later question. Use when an answer
   * changes *who the remaining questions are about* — e.g. a manager who should
   * answer for the person doing the role rather than for themselves. Without the
   * repeat it would be forgotten by question three.
   */
  lens?: string;
}

/**
 * What a question is for.
 * - `'scored'` (default): a real question. Scored, mapped, counted in progress.
 * - `'profile'`: classifies the taker rather than assessing them. Contributes
 *   nothing to the score or the map, carries no progress (so a quiz that
 *   promises "eight questions" still has eight), and always leads, ahead of any
 *   randomization. Its job is to set `tag` and/or `lens`.
 */
export type QuizQuestionKind = 'scored' | 'profile';

export interface QuizQuestion {
  id: string;
  section: string;
  text: string;
  reveal?: string;
  /** Defaults to `'scored'`. */
  kind?: QuizQuestionKind;
  options: QuizOption[];
}

/** True for questions that count toward the score, the map and the progress bar. */
export function isScored(question: QuizQuestion): boolean {
  return (question.kind ?? 'scored') === 'scored';
}

import type { ImageMetadata } from 'astro';

export interface QuizSection {
  id: string;
  label: string;
  blurb?: string;
  /**
   * Optional image rendered alongside the section card on the landing page.
   * `ImageMetadata` when the frontmatter uses a content-relative path
   * (Astro's `image()` helper resolves and optimizes it), or a plain string
   * for remote URLs and paths served from `public/`.
   */
  image?: string | ImageMetadata;
}

export interface QuizLevelThreshold {
  level: string;
  minScore: number;
  maxScore: number;
  title?: string;
}

/**
 * Selects the results-rendering strategy.
 * - `'band'` (default): total score maps to a level; `<ResultCard>` blocks render.
 * - `'map-move'`: renders a per-answer map plus one recommended move.
 */
export type ResultStyle = 'band' | 'map-move';

/**
 * Where the email capture sits in the flow.
 * - `'end'` (default): answer everything, then hand over an email to see results.
 * - `'start'`: capture is a hard gate before question 1. The taker knows up front
 *   that an email is involved, which self-qualifies for higher intent. Note that
 *   nothing is answered yet at submit time, so a result-tier tag
 *   (`levelTagPrefix`) cannot be applied on a start gate.
 */
export type CapturePosition = 'start' | 'end';

/** Tints available to a "how it works" step chip. */
export type QuizStepTone = 'accent' | 'valuable' | 'slipping' | 'alt';

/** One card in the cover's "how it works" strip. */
export interface QuizHowItWorksStep {
  /** Small label above the title, e.g. "step 1". */
  label?: string;
  title: string;
  body?: string;
  icon?: string;
  tone?: QuizStepTone;
}

/** Copy + selection config consumed by the map-move results renderer. */
export interface MapMoveConfig {
  /** Question ids in priority order; the reclaim move picks the first slipping one. */
  reclaimPriority: string[];
  /** Question ids in priority order; the redirect move picks the first slipping one. */
  redirectPriority: string[];
  /** Small label above the result heading, e.g. "your result". */
  eyebrow?: string;
  /** The result page's heading. Deliberately not a grade or an archetype. */
  heading?: string;
  opening?: string;
  /** Label above the balance bar, e.g. "Where your recent sprints went". */
  balanceLabel?: string;
  gainingHeading: string;
  gainingEmpty?: string;
  slippingHeading: string;
  slippingEmpty?: string;
  moveHeading?: string;
  contextHeading?: string;
  wellPositioned?: string;
  /**
   * Shown when there is no move to make and the taker is not well positioned
   * either, i.e. nothing was decisive enough to point at (every answer landed
   * in the middle). Without it the payoff block is dropped rather than rendered
   * empty.
   */
  noMove?: string;
  close?: string;
  framing?: {
    gaining: string;
    mixed: string;
    slipping: string;
  };
  /** Footer row: a line of secondary text and one accent link. */
  cta?: {
    body?: string;
    buttonLabel: string;
    buttonHref: string;
  };
}

export interface QuizData {
  title: string;
  description?: string;
  intro?: string;
  resultsSubtitle?: string;
  resultStyle?: ResultStyle;
  capturePosition?: CapturePosition;
  /** Cover strip that shows what the taker is signing up for, before they do. */
  howItWorks?: QuizHowItWorksStep[];
  sections: QuizSection[];
  questions: QuizQuestion[];
  sectionLevels?: QuizLevelThreshold[];
  overallLevels?: QuizLevelThreshold[];
  mapMove?: MapMoveConfig;
  /**
   * Controls the order in which questions are presented to the user.
   * - `'none'` (default): preserve the order declared in frontmatter.
   * - `'within-sections'`: keep the section order from frontmatter, but
   *   shuffle the questions within each section. Section labels still
   *   appear in their declared order; only the questions inside each
   *   section are randomized.
   * Scoring is order-independent (keyed by question id), so this only
   * affects presentation.
   */
  randomize?: 'none' | 'within-sections';
  /**
   * Controls option order within each question.
   * - `'none'` (default): show options in the declared order.
   * - `'shuffle'`: randomize option order per visit so a fixed
   *   slipping/mixed/gaining/context order never gives away the "best" answer.
   * Decided once on mount and stable across re-renders and the back button.
   * Scoring is keyed by the option's original index, so this affects
   * presentation only.
   */
  randomizeOptions?: 'none' | 'shuffle';
}

export type QuizResponses = Record<string, number>;

export interface QuizResult {
  total: number;
  maxTotal: number;
  sectionScores: Record<string, number>;
  sectionLevels: Record<string, string>;
  overallLevel: string;
  overallTitle?: string;
}

/** One classified answer in a map-move result. */
export interface MapMoveEntry {
  questionId: string;
  optionIndex: number;
  bucket: MapMoveBucket;
  /** The map line for this answer (from the chosen option's `mapSentence`). */
  sentence?: string;
}

/** A selected move target plus the copy to render for it. */
export interface MapMoveTarget {
  entry: MapMoveEntry;
  sentence?: string;
}

export interface MapMoveResult {
  gaining: MapMoveEntry[];
  slipping: MapMoveEntry[];
  context: MapMoveEntry[];
  /** Highest-priority slipping answer to reclaim time from, or null if none slips. */
  reclaim: MapMoveTarget | null;
  /** Highest-priority slipping answer to redirect the reclaimed time into. */
  redirect: MapMoveTarget | null;
  /**
   * Slipping answers other than the reclaim/redirect targets. Exposed for
   * consumers that want them, but the built-in renderer does not print them:
   * their sentences are the same `mapSentence` strings the slipping column
   * already shows, so repeating them here only diluted the one move.
   */
  otherSlipping: MapMoveEntry[];
  /** True when nothing is slipping — the "rare case" fallback. */
  wellPositioned: boolean;
  /** Light framing bucket for the descriptive line, or null when no framing copy exists. */
  framing: 'gaining' | 'mixed' | 'slipping' | null;
  /**
   * Segment widths for the balance bar, as whole percentages that sum to 100.
   * A proportion, never a score: the result page shows the bar with no number
   * on it. Null when no answer was decisive (all mixed or context), in which
   * case there is nothing honest to draw.
   */
  balance: { gainingPct: number; slippingPct: number } | null;
}

